text:
{
 "title": "令和6年能登半島地震災害の被災者に係る所得税法等の臨時特例法",
 "lead": {
  "es": "令和《れいわ》6年《ねん》の能登《のと》半島《はんとう》地震《じしん》で被害《ひがい》を受《う》けた人《ひと》の負担《ふたん》を軽《かる》くするため、令和《れいわ》5年《ねん》分《ぶん》の所得税《しょとくぜい》でとくべつな決《き》まりをつくった法律《ほうりつ》です。",
  "hs": "令和6年能登半島地震の｜被災者《ひさいしゃ》の負担を軽くするため、この災害による損失について、令和5年分の所得税で特別な｜措置《そち》をとる法律です。",
  "std": "令和6年能登半島地震災害の被災者の負担軽減のため、災害による損失について令和5年分の所得税で特別な措置を講ずる法律です。",
  "univ": "令和6年能登半島地震災害の被災者の負担の軽減を図るため、令和5年分の所得税について、今般の災害による損失に係る特別な措置を講ずる法律。"
 },
 "facts": [
  {
   "es": "この地震《じしん》で 家《いえ》や家具《かぐ》などに損害《そんがい》が出《で》たときは、令和《れいわ》5年《ねん》分《ぶん》の所得《しょとく》で、その損害《そんがい》の金額《きんがく》を「雑損《ざっそん》控除《こうじょ》」（税金《ぜいきん》を計算《けいさん》するときに 差《さ》し引《ひ》けるしくみ）の対象《たいしょう》にできます。",
   "hs": "この災害で住宅や家財などの資産に損失が出たときは、令和5年分の所得で、その損失の金額を｜雑損《ざっそん》｜控除《こうじょ》（税金の計算で差し引けるしくみ）の対象にできる。",
   "std": "今般の災害で住宅や家財等の資産に損失が生じたときは、令和5年分の所得において、その損失額を雑損控除の適用対象とすることができます。",
   "univ": "今般の災害により住宅や家財等の資産について損失が生じたときは、令和5年分の所得において、その損失の金額を雑損控除の適用対象とすることができる。"
  },
  {
   "es": "この地震《じしん》で 家《いえ》や家具《かぐ》に大《おお》きな被害《ひがい》を受《う》けたときは、雑損《ざっそん》控除《こうじょ》のかわりにえらんで、令和《れいわ》5年《ねん》分《ぶん》の所得税《しょとくぜい》を「災害《さいがい》減免法《げんめんほう》」で 軽《かる》くしたり なしにしたりしてもらえます。",
   "hs": "この災害で住宅や家財に大きな｜被害《ひがい》を受けたときは、｜雑損《ざっそん》｜控除《こうじょ》とどちらかを選んで、令和5年分の所得税について災害減免法による軽減・｜免除《めんじょ》を受けられる。",
   "std": "今般の災害で住宅や家財に甚大な被害を受けたときは、雑損控除との選択により、令和5年分の所得税について災害減免法による軽減免除を受けられます。",
   "univ": "今般の災害により住宅や家財について甚大な被害を受けたときは、雑損控除との選択により、令和5年分の所得税について、災害減免法による軽減免除の適用を受けることができる。"
  },
  {
   "es": "この地震《じしん》で 仕事《しごと》に使《つか》う財産《ざいさん》などに損害《そんがい》が出《で》たときは、その金額《きんがく》を、令和《れいわ》5年《ねん》分《ぶん》の仕事《しごと》のもうけを計算《けいさん》するときの 必要《ひつよう》なお金《かね》（必要《ひつよう》経費《けいひ》）に入《い》れられます。",
   "hs": "この災害で事業用の資産などに損失が出たときは、その損失の金額を、令和5年分の事業所得などの計算で必要経費に入れられる。",
   "std": "今般の災害で事業用資産等に損失が生じたときは、その損失額を、令和5年分の事業所得等の計算上、必要経費に算入できます。",
   "univ": "今般の災害により事業用資産等について損失が生じたときは、その損失の金額について、令和5年分の事業所得等の金額の計算上、必要経費に算入することができる。"
  },
  {
   "es": "この法律《ほうりつ》は、おおやけに知《し》らされた日《ひ》から使《つか》われます。",
   "hs": "この法律は、｜公布《こうふ》の日から｜施行《しこう》する。",
   "std": "公布の日から施行します。",
   "univ": "この法律は、公布の日から施行する。"
  }
 ]
}
